  }

  return (
    <ul>
      {todos.map((t) => (
        <li key={t.id}>
          {t.text}{" "}
          <button onClick={() => deleteTodo(t.id)}>ဖျက်မယ်</button>
        </li>
      ))}
    </ul>
  );
}

