function ProfileCard(props) {
  const [liked, setLiked] = useState(false);

  return (
    <div>
      <h2>{props.name}</h2>
      <p>{props.role}</p>
      <button onClick={() => setLiked(!liked)}>
        {liked ? "Liked ❤️" : "Like 🤍"}
      </button>
    </div>
  );
}

function App() {
  return <ProfileCard name="အောင်မင်း" role="React Developer" />;
}

